#!/usr/bin/env node
// Dependency-free Node test runner for _local/*.test.ts files.
import { spawn } from 'node:child_process';
import { readdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..', '..');

async function discoverTestFiles(root) {
  const results = [];
  async function walk(dir) {
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (entry.name === 'node_modules' || entry.name === '.git') continue;
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(full);
      } else if (entry.isFile() && entry.name.endsWith('.test.ts')) {
        results.push(full);
      }
    }
  }
  await walk(root);
  return results;
}

async function main() {
  const arg = process.argv[2];
  let files;

  if (arg) {
    const target = path.resolve(repoRoot, arg);
    const stat = await import('node:fs/promises').then((fs) => fs.stat(target).catch(() => null));
    if (stat && stat.isDirectory()) {
      files = await discoverTestFiles(target);
    } else {
      files = [target];
    }
  } else {
    files = await discoverTestFiles(path.join(repoRoot, '_local'));
  }

  if (files.length === 0) {
    console.error('No *.test.ts files found.');
    process.exit(1);
  }

  const child = spawn(
    process.execPath,
    ['--test', '--test-reporter=spec', '--no-warnings=MODULE_TYPELESS_PACKAGE_JSON', ...files],
    { cwd: repoRoot, stdio: 'inherit' },
  );

  child.on('exit', (code) => {
    process.exit(code ?? 1);
  });
}

main();

